mapper.select:
SELECT t.id AS transactionId, a.account_type AS accountType, a.account_name AS accountName, i.name AS institutionName, DATE_FORMAT(t.transaction_at, '%Y-%m-%dT%H:%i:%s+09:00') AS transactionAt, t.merchant_name AS merchantName, t.amount AS amount, t.direction AS direction, t.balance_after AS balanceAfter FROM mock_codef_transaction t JOIN mock_codef_account a ON a.id = t.account_id JOIN mock_codef_connection c ON c.id = a.connection_id JOIN mock_codef_institution i ON i.id = c.institution_id WHERE c.user_id = #{userId} AND i.is_supported = 1
AND DATE_FORMAT(t.transaction_at, '%Y-%m') = #{yearMonth}
ORDER BY t.transaction_at DESC, t.id DESC
